@Override
public synchronized List<SessionSummary> listSummaries() {
    requireOpen();
    var result = new ArrayList<SessionSummary>();
    try (Statement statement = connection.createStatement();
         ResultSet rows = statement.executeQuery(
                 "SELECT session_id, revision, document FROM ji_sessions ORDER BY created_at DESC")) {
        while (rows.next()) {
            String sessionId = rows.getString(1);
            long revision = rows.getLong(2);
            SessionDocument document = codec.decode(rows.getBytes(3));
            if (!document.metadata().sessionId().equals(sessionId) || document.revision() != revision) {
                throw new IllegalStateException("SQLite Session row and document revisions disagree");
            }
            result.add(SessionSummary.from(document));
        }
        return result.stream().sorted(java.util.Comparator.comparing(SessionSummary::updatedAt).reversed()).toList();
    } catch (SQLException exception) {
        throw storage("cannot list SQLite Session summaries", exception);
